/* Audition page for PCA directions. Loads manifest.js (generated by build_manifest.py, or by
   build_site.py for the published copy), which sets window.FADERSPACE_MANIFEST. One shared
   <audio> element plays one clip at a time. */
(() => {
  'use strict';

  let manifest = null;
  // Opens when the URL doesn't name an experiment (falls back to the manifest's first).
  const DEFAULT_EXPERIMENT = 'magentart_trumpet_6k';
  // 'mid' (examples near zero along the direction) is optional. Experiments that have it show one
  // group at a time, picked with the fader; the others show negative | positive side by side.
  const SIDES = ['neg', 'mid', 'pos'];
  const SIDE_NAME = { neg: 'Negative', mid: 'Middle', pos: 'Positive' };
  const SIDE_SIGN = { neg: '−', mid: '0', pos: '+' };
  const RANK_MEANS = { neg: 'strongest', mid: 'closest to zero', pos: 'strongest' };
  const LEVELS = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-_';
  // Over http(s), a direction's clips are fetched into memory as soon as it opens: switching is
  // instant and seeking works even on servers without range requests (python -m http.server).
  // Opened from disk, fetch() is blocked, so clips play straight from their files.
  const PREFETCH = location.protocol !== 'file:';
  // In-memory audio plays from blob: URLs, unless the page's content security policy refuses them
  // for media; the first such failure switches everything to data: URLs.
  let useDataUrls = false;

  const ICONS =
    '<svg class="i-play" viewBox="0 0 16 16" aria-hidden="true"><path d="M5 3.1v9.8a.6.6 0 0 0 .92.5l7.7-4.9a.6.6 0 0 0 0-1L5.92 2.6a.6.6 0 0 0-.92.5Z"/></svg>' +
    '<svg class="i-pause" viewBox="0 0 16 16" aria-hidden="true"><rect x="3.5" y="2.5" width="3" height="11" rx="1"/><rect x="9.5" y="2.5" width="3" height="11" rx="1"/></svg>';

  const $ = (id) => document.getElementById(id);
  const ui = {
    sidebar: document.querySelector('.sidebar'),
    main: $('main'),
    experiment: $('experiment'),
    summary: $('exp-summary'),
    grid: $('dir-grid'),
    config: $('config'),
    crumb: $('crumb'),
    title: $('title'),
    auto: $('auto'),
    prev: $('prev'),
    next: $('next'),
    keysSide: $('keys-side'),
    fader: $('fader'),
    faderInput: $('fader-input'),
    columns: { neg: $('column-neg'), mid: $('column-mid'), pos: $('column-pos') },
    lists: { neg: $('list-neg'), mid: $('list-mid'), pos: $('list-pos') },
    notes: { neg: $('note-neg'), mid: $('note-mid'), pos: $('note-pos') },
    details: $('details'),
    detailsTitle: $('details-title'),
    detailsMeta: $('details-meta'),
    detailsText: $('details-text'),
  };

  const player = new Audio();
  player.preload = 'auto';

  const state = {
    exp: null,
    dir: null,
    clips: { neg: [], mid: [], pos: [] },
    fader: false, // the open experiment has middle examples: one group at a time
    sel: { side: 'neg', rank: 0 }, // keyboard cursor
    current: null, // clip the user last asked to play; the only one that shows progress
    loaded: null, // clip whose audio is in the player
    pending: false, // a play request is waiting for its audio
    fetches: null, // AbortController for the open direction's prefetches
    bundle: null, // hosted copies: the open direction's clips in one file, fetched once
    autoAdvance: readPref('autoAdvance', true),
  };
  let request = 0; // bumped by every play/pause so a superseded async play() gives up
  let frame = 0;
  let palette = null;

  const canvasClip = new WeakMap();
  const resizer = new ResizeObserver((entries) => {
    for (const entry of entries) {
      const clip = canvasClip.get(entry.target);
      if (clip) drawWave(clip);
    }
  });

  // ---------- helpers ----------

  function readPref(key, fallback) {
    try {
      const value = localStorage.getItem(`faderspace.${key}`);
      return value === null ? fallback : JSON.parse(value);
    } catch {
      return fallback;
    }
  }

  function writePref(key, value) {
    try {
      localStorage.setItem(`faderspace.${key}`, JSON.stringify(value));
    } catch {
      /* storage unavailable (private mode): the preference just won't persist */
    }
  }

  const escapeHtml = (text) => String(text).replace(/[&<>"']/g, (c) => `&#${c.charCodeAt(0)};`);
  const encodePath = (path) => path.split('/').map(encodeURIComponent).join('/');
  const allClips = () => SIDES.flatMap((side) => state.clips[side]);
  const sidesWithClips = () => SIDES.filter((side) => state.clips[side].length);
  const selectedClip = () => state.clips[state.sel.side][state.sel.rank];
  const isPlaying = () => state.pending || (state.loaded !== null && !player.paused);
  const durationOf = (clip) => clip.duration || (clip === state.loaded && player.duration) || 0;
  const progressOf = (clip) => (clip === state.current && clip === state.loaded ? player.currentTime : 0);
  // The first key of a file name (e.g. "prompt" in neg_0_prompt_10_variant_9) identifies where a
  // clip came from; examples that share it are highlighted together.
  const groupKey = (clip) => Object.keys(clip.meta)[0];

  function formatTime(seconds) {
    const s = Math.max(0, Math.floor(seconds || 0));
    return `${Math.floor(s / 60)}:${String(s % 60).padStart(2, '0')}`;
  }

  /** Envelope string from the manifest -> sqrt-amplitude levels in 0..1 (drawn as-is). */
  function decodeLevels(text) {
    if (!text) return null;
    const levels = new Float32Array(text.length);
    for (let i = 0; i < text.length; i++) levels[i] = LEVELS.indexOf(text[i]) / 63;
    return levels;
  }

  // ---------- clips ----------

  function makeClip(dir, side, item, rank) {
    const clip = {
      side,
      rank,
      file: item.file,
      url: dir.path ? encodePath(`${dir.path}/${item.file}`) : null,
      bytes: item.bytes || null, // hosted copies: [start, end) of this clip within dir.bundle
      meta: item.meta || {},
      duration: item.dur || 0,
      peak: decodeLevels(item.peak),
      rms: decodeLevels(item.rms),
      source: null,
      blobUrl: null,
      failed: false,
      hoverX: null,
    };
    // Line N of the experiment's prompt list is the text of prompt_N (see build_manifest.py).
    clip.prompt = state.exp.prompts?.[clip.meta[groupKey(clip)]] ?? '';
    renderClip(clip);
    return clip;
  }

  function renderClip(clip) {
    const tags = Object.entries(clip.meta)
      .map(([key, value], i) =>
        `<span class="tag${i === 0 ? ' group' : ''}"><span class="tag-k">${escapeHtml(key)}</span> ${escapeHtml(value)}</span>`)
      .join('<span class="sep">·</span>');

    const li = document.createElement('li');
    li.className = 'clip';
    li.innerHTML = `
      <span class="rank" title="Rank ${clip.rank + 1} (1 = ${RANK_MEANS[clip.side]})">${clip.rank + 1}</span>
      <button class="play" type="button">${ICONS}</button>
      <canvas class="wave" aria-hidden="true"></canvas>
      <div class="clip-foot">
        <span class="tags" title="${escapeHtml(clip.file)}">${tags || escapeHtml(clip.file)}</span>
        <span class="time"></span>
      </div>
      ${clip.prompt ? `<p class="caption" title="${escapeHtml(clip.prompt)}">${escapeHtml(clip.prompt)}</p>` : ''}`;
    clip.el = li;
    clip.btn = li.querySelector('.play');
    clip.canvas = li.querySelector('.wave');
    clip.time = li.querySelector('.time');

    li.addEventListener('click', () => {
      if (getSelection().isCollapsed) toggle(clip); // dragging to copy text shouldn't toggle playback
    });
    clip.btn.addEventListener('click', (event) => {
      event.stopPropagation();
      toggle(clip);
    });
    clip.canvas.addEventListener('click', (event) => {
      event.stopPropagation();
      play(clip, (durationOf(clip) * event.offsetX) / clip.canvas.clientWidth);
    });
    clip.canvas.addEventListener('pointermove', (event) => {
      clip.hoverX = event.offsetX;
      drawWave(clip);
    });
    clip.canvas.addEventListener('pointerleave', () => {
      clip.hoverX = null;
      drawWave(clip);
    });
    const group = li.querySelector('.tag.group');
    if (group) {
      group.title = `Highlight examples from this ${groupKey(clip)}`;
      group.addEventListener('pointerenter', () => highlight(clip));
      group.addEventListener('pointerleave', () => highlight(null));
    }

    canvasClip.set(clip.canvas, clip);
    resizer.observe(clip.canvas);
    updateTime(clip);
  }

  function highlight(source) {
    const key = source && groupKey(source);
    for (const clip of allClips()) {
      clip.el.classList.toggle('related', Boolean(source) && clip.meta[key] === source.meta[key]);
    }
  }

  function columnNote(clips) {
    const key = clips.length ? groupKey(clips[0]) : null;
    const count = `${clips.length} example${clips.length === 1 ? '' : 's'}`;
    if (!key) return count;
    const distinct = new Set(clips.map((clip) => clip.meta[key])).size;
    return `${count} · ${distinct} ${key}${distinct === 1 ? '' : 's'}`;
  }

  // ---------- drawing ----------

  function readPalette() {
    const css = getComputedStyle(document.documentElement);
    const v = (name) => css.getPropertyValue(name).trim();
    palette = { neg: v('--neg'), mid: v('--mid'), pos: v('--pos'), peak: v('--wave-peak'), rms: v('--wave-rms'), cursor: v('--muted') };
  }

  /** Outline of an envelope mirrored around the midline, one point per bucket. */
  function envelopePath(ctx, levels, w, mid) {
    const n = levels.length;
    const x = (i) => ((i + 0.5) * w) / n;
    ctx.beginPath();
    ctx.moveTo(0, mid - levels[0] * mid);
    for (let i = 0; i < n; i++) ctx.lineTo(x(i), mid - levels[i] * mid);
    ctx.lineTo(w, mid - levels[n - 1] * mid);
    ctx.lineTo(w, mid + levels[n - 1] * mid);
    for (let i = n - 1; i >= 0; i--) ctx.lineTo(x(i), mid + levels[i] * mid);
    ctx.lineTo(0, mid + levels[0] * mid);
    ctx.closePath();
  }

  function drawWave(clip) {
    const { canvas } = clip;
    const w = canvas.clientWidth;
    const h = canvas.clientHeight;
    if (!w || !h) return;
    const dpr = window.devicePixelRatio || 1;
    if (canvas.width !== Math.round(w * dpr) || canvas.height !== Math.round(h * dpr)) {
      canvas.width = Math.round(w * dpr);
      canvas.height = Math.round(h * dpr);
    }
    const ctx = canvas.getContext('2d');
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    ctx.clearRect(0, 0, w, h);

    const accent = palette[clip.side];
    const total = durationOf(clip);
    const time = progressOf(clip);
    const playedX = total ? Math.min(1, time / total) * w : 0;
    const mid = h / 2;
    const snap = (x) => Math.round(x * dpr) / dpr;

    if (clip.peak) {
      // Peak envelope as a soft halo around the RMS envelope; the played part is redrawn in the accent.
      envelopePath(ctx, clip.peak, w, mid);
      ctx.fillStyle = palette.peak;
      ctx.fill();
      envelopePath(ctx, clip.rms, w, mid);
      ctx.fillStyle = palette.rms;
      ctx.fill();
      if (playedX > 0) {
        ctx.save();
        ctx.beginPath();
        ctx.rect(0, 0, playedX, h);
        ctx.clip();
        ctx.clearRect(0, 0, playedX, h);
        ctx.fillStyle = accent;
        envelopePath(ctx, clip.peak, w, mid);
        ctx.globalAlpha = 0.35;
        ctx.fill();
        envelopePath(ctx, clip.rms, w, mid);
        ctx.globalAlpha = 1;
        ctx.fill();
        ctx.restore();
      }
    } else {
      // No envelope in the manifest (e.g. not a 16/32-bit WAV): a plain progress track.
      ctx.fillStyle = palette.peak;
      ctx.fillRect(0, mid - 1, w, 2);
      ctx.fillStyle = accent;
      ctx.fillRect(0, mid - 1, playedX, 2);
    }

    if (time > 0) {
      ctx.fillStyle = accent;
      ctx.fillRect(Math.min(w - 1.5, snap(playedX)), 0, 1.5, h);
    }
    if (clip.hoverX !== null) {
      ctx.fillStyle = palette.cursor;
      ctx.globalAlpha = 0.7;
      ctx.fillRect(snap(clip.hoverX), 0, 1, h);
      ctx.globalAlpha = 1;
    }
  }

  function updateTime(clip) {
    const total = durationOf(clip);
    if (clip.failed) clip.time.textContent = 'Could not load audio';
    else if (clip === state.current) clip.time.textContent = `${formatTime(progressOf(clip))} / ${formatTime(total)}`;
    else clip.time.textContent = total ? formatTime(total) : '';
  }

  function paint(clip) {
    drawWave(clip);
    updateTime(clip);
  }

  function syncButtons() {
    for (const clip of allClips()) {
      const playing = clip === state.current && isPlaying();
      clip.el.classList.toggle('playing', playing);
      clip.el.classList.toggle('loading', clip === state.current && state.pending);
      clip.btn.setAttribute('aria-label', `${playing ? 'Pause' : 'Play'} ${SIDE_NAME[clip.side].toLowerCase()} example ${clip.rank + 1}`);
    }
  }

  function tick() {
    frame = 0;
    if (state.loaded) paint(state.loaded);
    if (!player.paused) frame = requestAnimationFrame(tick);
  }

  // ---------- playback ----------

  /** A URL the player can load for `clip`, or null if its audio can't be fetched. */
  function sourceFor(clip) {
    if (!PREFETCH) return Promise.resolve(clip.url);
    clip.source ??= audioBlob(clip)
      .then((blob) => (useDataUrls ? dataUrl(blob) : (clip.blobUrl = URL.createObjectURL(blob))))
      .catch((err) => {
        if (err.name === 'AbortError') throw err;
        return clip.url; // a loose file can still be tried directly (the player reports the error)
      });
    return clip.source;
  }

  function audioBlob(clip) {
    if (!clip.bytes) return fetchBlob(clip.url);
    state.bundle ??= fetchBlob(encodePath(state.dir.bundle));
    return state.bundle.then((bundle) => bundle.slice(clip.bytes[0], clip.bytes[1], 'audio/mpeg'));
  }

  function fetchBlob(url) {
    return fetch(url, { signal: state.fetches.signal }).then((res) =>
      res.ok ? res.blob() : Promise.reject(new Error(`HTTP ${res.status}`)),
    );
  }

  function dataUrl(blob) {
    return new Promise((resolve, reject) => {
      const reader = new FileReader();
      reader.onload = () => resolve(reader.result);
      reader.onerror = () => reject(reader.error);
      reader.readAsDataURL(blob);
    });
  }

  function prefetch() {
    if (!PREFETCH) return;
    const first = selectedClip();
    for (const clip of [first, ...allClips().filter((c) => c !== first)]) {
      if (clip) sourceFor(clip).catch(() => {});
    }
  }

  /** Play `clip`, from `at` seconds if given. Switching clips always starts the new one from 0. */
  async function play(clip, at = null) {
    if (!clip || clip.failed) return;
    const id = ++request;
    if (state.current !== clip) {
      const previous = state.current;
      state.current = clip;
      if (state.loaded) {
        player.pause();
        player.currentTime = 0;
      }
      if (previous) paint(previous);
    }
    state.pending = true;
    select(clip.side, clip.rank, { follow: false });
    syncButtons();

    let src;
    try {
      src = await sourceFor(clip);
    } catch {
      return; // prefetch aborted: the direction changed
    }
    if (id !== request) return;
    if (!src) {
      fail(clip);
      return;
    }
    if (state.loaded !== clip) {
      state.loaded = clip;
      player.src = src;
    }
    if (at !== null) player.currentTime = at;
    try {
      await player.play();
    } catch {
      // Interrupted by a newer request, or the clip failed to load ('error' handles that).
    } finally {
      if (id === request) {
        state.pending = false;
        syncButtons();
      }
    }
  }

  function pause() {
    request++;
    state.pending = false;
    player.pause();
    syncButtons();
  }

  function toggle(clip) {
    if (clip === state.current && isPlaying()) pause();
    else play(clip);
  }

  function stop() {
    pause();
    const clip = state.current;
    state.current = null;
    if (state.loaded) player.currentTime = 0;
    if (clip) paint(clip);
  }

  player.addEventListener('play', () => {
    syncButtons();
    if (!frame) frame = requestAnimationFrame(tick);
  });
  player.addEventListener('pause', () => {
    syncButtons();
    if (state.loaded) paint(state.loaded);
  });
  // rAF drives the smooth playhead; timeupdate keeps the readout right wherever rAF is throttled.
  player.addEventListener('timeupdate', () => state.loaded && paint(state.loaded));
  player.addEventListener('seeked', () => state.loaded && paint(state.loaded));
  player.addEventListener('loadedmetadata', () => state.loaded && paint(state.loaded));

  player.addEventListener('ended', () => {
    const clip = state.loaded;
    const next = clip && state.clips[clip.side][clip.rank + 1];
    if (state.autoAdvance && next) {
      play(next);
      return;
    }
    player.currentTime = 0;
    if (clip) paint(clip);
    syncButtons();
  });

  player.addEventListener('error', () => {
    const clip = state.loaded;
    if (!clip || !player.getAttribute('src')) return;
    if (!useDataUrls && player.src.startsWith('blob:')) {
      // Probably a content policy that refuses blob: media: rebuild every source as a data: URL and retry.
      useDataUrls = true;
      for (const c of allClips()) {
        if (c.blobUrl) URL.revokeObjectURL(c.blobUrl);
        c.blobUrl = c.source = null;
      }
      state.loaded = null;
      play(clip);
      return;
    }
    fail(clip);
  });

  function fail(clip) {
    clip.failed = true;
    clip.el.classList.add('error');
    request++;
    state.pending = false;
    player.pause(); // a failed load leaves `paused` false
    syncButtons();
    updateTime(clip);
  }

  // ---------- selection & navigation ----------

  /** Move the keyboard cursor. If audio is playing, playback follows the cursor. */
  function select(side, rank, { follow = true } = {}) {
    const list = state.clips[side];
    if (!list.length) return;
    rank = Math.max(0, Math.min(list.length - 1, rank));
    const changed = side !== state.sel.side || rank !== state.sel.rank;
    state.sel = { side, rank };
    showSide(side);
    for (const clip of allClips()) clip.el.classList.toggle('selected', clip === list[rank]);
    showDetails(list[rank]);
    if (changed) list[rank].el.scrollIntoView({ block: 'nearest' });
    if (follow && changed && isPlaying()) play(list[rank]);
  }

  /** Two-column experiments show negative | positive; fader experiments show only `side`. */
  function showSide(side) {
    for (const s of SIDES) ui.columns[s].hidden = state.fader ? s !== side : s === 'mid';
    if (!state.fader) return;
    ui.fader.className = `fader ${side}`;
    ui.faderInput.value = SIDES.indexOf(side);
    ui.faderInput.setAttribute('aria-valuetext', SIDE_NAME[side]);
    for (const stop of ui.fader.querySelectorAll('[data-side]')) {
      stop.setAttribute('aria-pressed', String(stop.dataset.side === side));
    }
  }

  /** Full prompt of the selected example (cards only show the first two lines). */
  function showDetails(clip) {
    ui.details.hidden = !clip.prompt;
    ui.details.className = `details ${clip.side}`;
    ui.details.querySelector('.sign').textContent = SIDE_SIGN[clip.side];
    ui.detailsTitle.textContent = `${SIDE_NAME[clip.side]} #${clip.rank + 1}`;
    ui.detailsMeta.textContent = Object.entries(clip.meta).map(([key, value]) => `${key} ${value}`).join(' · ');
    ui.detailsText.textContent = clip.prompt;
  }

  function closeDirection() {
    request++;
    state.pending = false;
    player.pause();
    player.removeAttribute('src');
    player.load();
    state.current = state.loaded = null;
    state.fetches?.abort();
    state.bundle = null;
    for (const clip of allClips()) {
      resizer.unobserve(clip.canvas);
      if (clip.blobUrl) URL.revokeObjectURL(clip.blobUrl);
    }
  }

  function openDirection(dir) {
    if (!dir || dir === state.dir) return;
    const resume = isPlaying();
    closeDirection();
    state.dir = dir;
    state.fetches = PREFETCH ? new AbortController() : null;

    for (const side of SIDES) {
      state.clips[side] = (dir[side] || []).map((item, i) => makeClip(dir, side, item, i));
      ui.lists[side].replaceChildren(...state.clips[side].map((clip) => clip.el));
      ui.notes[side].textContent = columnNote(state.clips[side]);
    }

    const dirs = state.exp.directions;
    const index = dirs.indexOf(dir);
    [...ui.grid.children].forEach((chip, i) => chip.setAttribute('aria-current', String(i === index)));
    revealChip(ui.grid.children[index]);
    ui.prev.disabled = index === 0;
    ui.next.disabled = index === dirs.length - 1;
    ui.crumb.textContent = state.exp.name;
    ui.title.textContent = `Direction ${dir.id}`;
    document.title = `Direction ${dir.id} · ${state.exp.name} · faderspace`;
    try {
      history.replaceState(null, '', `#${encodeURIComponent(state.exp.name)}.${dir.id}`);
    } catch {
      /* some browsers refuse history updates for file:// pages */
    }

    // Keep the side across directions, unless this one has no examples there (e.g. no middle).
    const side = state.clips[state.sel.side].length ? state.sel.side : sidesWithClips()[0];
    if (side) select(side, state.sel.rank, { follow: false });
    if (resume) play(selectedClip());
    prefetch();
  }

  /** Keep the active chip visible inside its scroller (sidebar, or the chip strip on phones) without moving the page. */
  function revealChip(chip) {
    const c = chip.getBoundingClientRect();
    const strip = ui.grid.getBoundingClientRect();
    ui.grid.scrollLeft += c.left - strip.left - (strip.width - c.width) / 2;
    const side = ui.sidebar.getBoundingClientRect();
    if (c.top < side.top || c.bottom > side.bottom) ui.sidebar.scrollTop += c.top - side.top - side.height / 2;
  }

  function step(delta) {
    const dirs = state.exp.directions;
    openDirection(dirs[dirs.indexOf(state.dir) + delta]);
  }

  function openExperiment(exp, dirId) {
    state.exp = exp;
    state.fader = exp.directions.some((d) => d.mid?.length);
    ui.experiment.value = exp.name;
    ui.main.classList.toggle('single', state.fader);
    ui.fader.hidden = !state.fader;
    ui.keysSide.textContent = state.fader ? 'Move the fader (− / 0 / +)' : 'Negative / positive side';

    const sizes = new Set(exp.directions.flatMap((d) => SIDES.filter((side) => d[side]).map((side) => d[side].length)));
    const perSide = sizes.size === 1 ? `${[...sizes][0]}` : `up to ${Math.max(...sizes)}`;
    ui.summary.textContent = `${exp.directions.length} directions · ${perSide} examples per ${state.fader ? 'group' : 'side'}`;

    ui.grid.replaceChildren(
      ...exp.directions.map((dir) => {
        const chip = document.createElement('button');
        chip.type = 'button';
        chip.className = 'dir-chip';
        chip.textContent = dir.id;
        chip.title = `Direction ${dir.id}`;
        chip.addEventListener('click', () => openDirection(dir));
        return chip;
      }),
    );

    ui.config.hidden = !exp.config;
    ui.config.querySelector('pre').textContent = exp.config || '';
    openDirection(exp.directions.find((d) => d.id === dirId) || exp.directions[0]);
  }

  function setAutoAdvance(on) {
    state.autoAdvance = on;
    ui.auto.setAttribute('aria-checked', String(on));
    writePref('autoAdvance', on);
  }

  /** Open the view named by `#<experiment>.<direction>` (or the older `#<experiment>/<direction>`). */
  function route() {
    let hash = location.hash.slice(1);
    try {
      hash = decodeURIComponent(hash);
    } catch {
      /* malformed escape: use it as typed */
    }
    const [, name, id] = /^(.*?)(?:[./](\d+))?$/.exec(hash);
    const exp =
      manifest.experiments.find((e) => e.name === name) ||
      manifest.experiments.find((e) => e.name === DEFAULT_EXPERIMENT) ||
      manifest.experiments[0];
    const dirId = Number.parseInt(id, 10);
    if (exp !== state.exp) openExperiment(exp, dirId);
    else openDirection(exp.directions.find((d) => d.id === dirId));
  }

  // ---------- input ----------

  document.addEventListener('keydown', (event) => {
    if (!state.dir || event.metaKey || event.ctrlKey || event.altKey) return;
    // The fader is a range input, but its arrows should still mean what they mean everywhere else.
    if (event.target.closest?.('select, input:not([type="range"]), textarea')) return;
    const { side, rank } = state.sel;
    switch (event.key) {
      case ' ':
        if (!event.repeat) toggle(selectedClip());
        break;
      case 'ArrowUp':
        select(side, rank - 1);
        break;
      case 'ArrowDown':
        select(side, rank + 1);
        break;
      case 'ArrowLeft':
      case 'ArrowRight': {
        // One step along neg → mid → pos (just neg ↔ pos for two-column experiments), same rank.
        const sides = sidesWithClips();
        const i = sides.indexOf(side) + (event.key === 'ArrowLeft' ? -1 : 1);
        select(sides[Math.max(0, Math.min(sides.length - 1, i))], rank);
        break;
      }
      case '[':
        step(-1);
        break;
      case ']':
        step(1);
        break;
      case 'a':
      case 'A':
        setAutoAdvance(!state.autoAdvance);
        break;
      case 'Escape':
        stop();
        break;
      default: {
        const clip = /^[1-9]$/.test(event.key) && state.clips[side][Number(event.key) - 1];
        if (!clip) return;
        play(clip, 0);
      }
    }
    event.preventDefault();
  });

  // Space is handled above; don't let it also "click" whichever button has focus.
  document.addEventListener('keyup', (event) => {
    if (event.key === ' ' && event.target.closest?.('button')) event.preventDefault();
  });

  // ---------- start ----------

  function renderEmpty() {
    for (const section of ui.sidebar.querySelectorAll('.side-section, .shortcuts')) section.hidden = true;
    ui.main.innerHTML = `
      <div class="empty">
        <h2>No experiments indexed yet</h2>
        <p>Put each experiment under <code>assets/&lt;experiment&gt;/direction_&lt;k&gt;/</code>, then run</p>
        <p><code>python3 build_manifest.py</code></p>
        <p>in this folder and reload the page.</p>
      </div>`;
  }

  function start() {
    manifest = window.FADERSPACE_MANIFEST;
    if (!manifest?.experiments?.length) {
      renderEmpty();
      return;
    }

    readPalette();
    matchMedia('(prefers-color-scheme: dark)').addEventListener('change', () => {
      readPalette();
      allClips().forEach(drawWave);
    });

    ui.experiment.replaceChildren(...manifest.experiments.map((exp) => new Option(exp.name, exp.name)));
    ui.experiment.addEventListener('change', () => {
      openExperiment(manifest.experiments.find((e) => e.name === ui.experiment.value), state.dir?.id);
      ui.experiment.blur();
    });
    ui.faderInput.addEventListener('input', () => select(SIDES[ui.faderInput.value], state.sel.rank));
    for (const stop of ui.fader.querySelectorAll('[data-side]')) {
      stop.addEventListener('click', () => select(stop.dataset.side, state.sel.rank));
    }
    ui.auto.addEventListener('click', () => setAutoAdvance(!state.autoAdvance));
    ui.prev.addEventListener('click', () => step(-1));
    ui.next.addEventListener('click', () => step(1));
    window.addEventListener('hashchange', route);

    setAutoAdvance(state.autoAdvance);
    route();
  }

  // Cache-bust the manifest so a rebuild shows up on a plain reload.
  const script = document.createElement('script');
  script.src = `manifest.js?v=${Date.now()}`;
  script.onload = script.onerror = start;
  document.head.append(script);
})();
